import{_ as i,C as s,o,c as r,a9 as l,E as a}from"./chunks/framework.asyjyako.js";const g=JSON.parse('{"title":"Collectors","description":"","frontmatter":{},"headers":[],"relativePath":"reference/checks.md","filePath":"reference/checks.md","lastUpdated":null}'),n={name:"reference/checks.md"};function c(d,t,h,p,k,u){const e=s("DocMedia");return o(),r("div",null,[t[0]||(t[0]=l('<p><a id="Check-catalog"></a><a id="Implemented-backends"></a></p><h1 id="Collectors" tabindex="-1">Collectors <a class="header-anchor" href="#Collectors" aria-label="Permalink to &quot;Collectors {#Collectors}&quot;">​</a></h1><p>A <strong>check type</strong> selects how a workload is measured. Each runs in an isolated worker with the chosen collector.</p><ul><li><p>Use a benchmark to decide <strong>whether</strong> a regression exists.</p></li><li><p>Use a profile to find <strong>where</strong> the cost moved.</p></li><li><p>Use network collectors for traffic, with attention to attribution.</p></li></ul><h2 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h2><p><a id="BenchmarkTools:-elapsed-time-and-allocation-cost"></a></p><h3 id=":benchmark-BenchmarkTools" tabindex="-1"><code>:benchmark</code> (BenchmarkTools) <a class="header-anchor" href="#:benchmark-BenchmarkTools" aria-label="Permalink to &quot;`:benchmark` (BenchmarkTools) {#:benchmark-BenchmarkTools}&quot;">​</a></h3><p>Elapsed time, GC time, allocated bytes and allocation count. The default choice.</p><ul><li><p>Inspect the distribution, not only the median.</p></li><li><p>Preparation outside the measured expression is excluded.</p></li><li><p>Requires BenchmarkTools.</p></li></ul><p><a id="Chairmarks:-another-repeated-measurement-collector"></a></p><h3 id=":chairmark-Chairmarks" tabindex="-1"><code>:chairmark</code> (Chairmarks) <a class="header-anchor" href="#:chairmark-Chairmarks" aria-label="Permalink to &quot;`:chairmark` (Chairmarks) {#:chairmark-Chairmarks}&quot;">​</a></h3><p>The same quantities as a low-overhead alternative for short measurements.</p><ul><li><p>Time is in seconds; GC is a <strong>fraction</strong> of elapsed time, not seconds.</p></li><li><p>Do not merge BenchmarkTools and Chairmarks samples into one distribution.</p></li></ul><h2 id="Profiles" tabindex="-1">Profiles <a class="header-anchor" href="#Profiles" aria-label="Permalink to &quot;Profiles {#Profiles}&quot;">​</a></h2><p><a id="CPU-profiling:-find-frequently-observed-call-paths"></a></p><h3 id=":profile-—-CPU-samples" tabindex="-1"><code>:profile</code> — CPU samples <a class="header-anchor" href="#:profile-—-CPU-samples" aria-label="Permalink to &quot;`:profile` — CPU samples {#:profile-—-CPU-samples}&quot;">​</a></h3><p>Sampling profiler call stacks. A sample is not a call count.</p><ul><li><p>Follow a wide branch into its callees and inspect the source.</p></li><li><p>An empty capture is missing evidence, not a zero-cost function.</p></li></ul><p><a id="Wall-time-profiling:-investigate-tasks-and-waiting"></a></p><h3 id=":wall_profile-—-task-wall-time-samples" tabindex="-1"><code>:wall_profile</code> — task wall-time samples <a class="header-anchor" href="#:wall_profile-—-task-wall-time-samples" aria-label="Permalink to &quot;`:wall_profile` — task wall-time samples {#:wall_profile-—-task-wall-time-samples}&quot;">​</a></h3><p>Captures task stacks, including tasks that are waiting. Requires Julia 1.12 or later.</p><ul><li>Use it when elapsed time is high but CPU samples do not explain it.</li></ul><p><a id="Allocation-profiling:-find-where-objects-are-created"></a></p><h3 id=":profile_alloc-—-allocation-stacks" tabindex="-1"><code>:profile_alloc</code> — allocation stacks <a class="header-anchor" href="#:profile_alloc-—-allocation-stacks" aria-label="Permalink to &quot;`:profile_alloc` — allocation stacks {#:profile_alloc-—-allocation-stacks}&quot;">​</a></h3><p>Sampled allocation events with types and call stacks.</p><ul><li><p>Bytes weight the amount; event counts weight the frequency. They can rank hotspots differently.</p></li><li><p>Julia-managed sampling does not cover native allocations.</p></li></ul><p>Read <code>qualification[&quot;allocation_profile&quot;]</code> together with the sites. An empty site table does not establish that the workload allocated nothing:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Status</th><th style="text-align:right;">Interpretation</th></tr></thead><tbody><tr><td style="text-align:right;"><code>complete</code></td><td style="text-align:right;">Target source sites were retained; inspect attribution counts and scope</td></tr><tr><td style="text-align:right;"><code>zero_allocations</code></td><td style="text-align:right;">The separate byte and allocation-count measurements were both zero</td></tr><tr><td style="text-align:right;"><code>no_samples</code></td><td style="text-align:right;">No allocation events were sampled; measured totals may still be positive</td></tr><tr><td style="text-align:right;"><code>outside_target_scope</code></td><td style="text-align:right;">Events were captured, but their source sites were outside the selected target</td></tr><tr><td style="text-align:right;"><code>unattributed_samples</code></td><td style="text-align:right;">Events were captured without a usable source site</td></tr></tbody></table><p>The record preserves measured <code>total_bytes</code> and <code>total_allocations</code>, raw and attributed sample counts, sample rate, repetitions, a message and weight semantics. Bytes and allocation count come from <strong>two independently prepared evaluations</strong>, rather than one common observation. Legacy profile plots distribute these measured totals over retained stacks; scenario profiles retain raw sampled weights. Keep those definitions distinct. Empty profiles retain their status and totals and do not produce invented source sites or a zero-valued flame graph. Scenario results also expose the independent whole-operation totals as separate observations, with <code>independent_operation_total</code> weight semantics and <code>whole_operation</code> scope. A successfully collected empty profile can belong to a functionally complete bundle; its qualification and diagnostics still determine what the profile supports. It does not establish a performance improvement.</p><p>CSV profile caches retain this qualification in a matching <code>.csv.allocation-profile.toml</code> sidecar. A legacy cache without it is recomputed instead of guessing what an empty table meant. <a id="Line-allocation-tracking:-attribute-bytes-to-source"></a></p><h3 id=":alloc-—-allocation-by-source-line" tabindex="-1"><code>:alloc</code> — allocation by source line <a class="header-anchor" href="#:alloc-—-allocation-by-source-line" aria-label="Permalink to &quot;`:alloc` — allocation by source line {#:alloc-—-allocation-by-source-line}&quot;">​</a></h3><p>Allocation bytes attributed to file and line.</p><ul><li>Totals depend on collection scope and repetition; do not compare them with a per-call estimate.</li></ul><p>Julia&#39;s line-allocation tracker creates <code>source.jl.&lt;worker-pid&gt;.mem</code> beside the sources it executes. PerfChecker records each worker&#39;s ownership before your preparation and measured code run. After success, a preparation or measurement error, or cancellation, it waits for the worker to stop and removes that worker&#39;s new traces. Files from other processes and unrelated <code>.mem</code> files are preserved. If a reused worker PID overwrites an existing trace, PerfChecker reads the new measurement and restores the previous bytes and permissions afterwards.</p><p>For asynchronous suites, call <code>cancel_suite!(job)</code> and then <code>wait_suite(job)</code>; the cancellation request alone does not mean cleanup has finished. A cleanup failure is reported as a failure, including the retained private inventory directory, even when cancellation was requested. That directory contains the worker PID, known source roots and a journal including saved original trace bytes. If writing the inventory metadata also fails, that error is included in the failure and the already saved journal is retained. PerfChecker does not automatically delete old traces from earlier runs: inspect the reported paths and resolve the filesystem or process error first.</p><p>The inventory covers the worker environment, development dependencies, package depots, Julia standard libraries and files loaded through ordinary <code>include</code>. A direct <code>include_string</code> that invents a filename outside those roots is not covered by the include journal. A forcibly killed controller, power loss or repeated interruption that prevents its cleanup code from running can leave traces; no blanket deletion of a package&#39;s <code>.mem</code> files is performed on restart. <a id="Network-collectors:-payload,-traffic-and-attribution"></a></p><h2 id="Network" tabindex="-1">Network <a class="header-anchor" href="#Network" aria-label="Permalink to &quot;Network {#Network}&quot;">​</a></h2><ul><li><p><code>:network</code> — counters the workload reports. Safe to gate CI on those counters.</p></li><li><p><code>:network_interface</code> — shared host interface. Not CI-worthy unless the machine is hermetic.</p></li><li><p><code>:network_isolated</code> — dedicated network namespace. Safe to gate CI.</p></li></ul><p>See <a href="./../network-measurement">Network measurement</a> for attribution and which counts double on loopback. <a id="One-feature,-several-checks"></a></p><h2 id="One-workload,-several-checks" tabindex="-1">One workload, several checks <a class="header-anchor" href="#One-workload,-several-checks" aria-label="Permalink to &quot;One workload, several checks {#One-workload,-several-checks}&quot;">​</a></h2><p>Give several <code>FeatureSpec</code> entries the same <code>workload</code> identifier and different <code>backend</code>s. Interfaces then group them under one operation and let the user pick the check type.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    FeatureSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:import_bibtex_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; workload </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :import_bibtex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, backend </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :benchmark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, entrypoint </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;features/import_bibtex.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    FeatureSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:import_bibtex_alloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; workload </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :import_bibtex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, backend </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :profile_alloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, entrypoint </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;features/import_bibtex.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The entrypoint is ordinary Julia and must return the same result for every target. Keep fixture construction outside the measured expression when setup is not part of the contract.</p><h2 id="Choosing-evidence" tabindex="-1">Choosing evidence <a class="header-anchor" href="#Choosing-evidence" aria-label="Permalink to &quot;Choosing evidence {#Choosing-evidence}&quot;">​</a></h2><ul><li>Never compare values whose measurement-definition IDs or comparison keys are incompatible. See the <a href="./../measurement-model">measurement model</a>.</li></ul><h2 id="Recorded-examples" tabindex="-1">Recorded examples <a class="header-anchor" href="#Recorded-examples" aria-label="Permalink to &quot;Recorded examples {#Recorded-examples}&quot;">​</a></h2>',46)),a(e,{src:"/examples/bibliography/figures/history-samples.svg",alt:"Nine groups containing all 900 export timings, with median markers and visible slow samples",caption:"Each dot is one sample; the dark marks are medians. Horizontal displacement only separates dots. Overlap and slow observations remain visible."}),a(e,{src:"/examples/bibliography/figures/profile-cpu.png",alt:"Recorded Bibliography export flame graph weighted by CPU samples",caption:"A real capture at revision 575ec81, weighted by CPU samples. Width includes descendants; the 40 highest-weight stacks are retained. Open the interactive profiles to zoom and inspect full call paths."}),a(e,{src:"/examples/bibliography/figures/profile-wall.png",alt:"Recorded Bibliography export flame graph weighted by task stack samples",caption:"A real capture at revision 575ec81, weighted by task stack samples. Width includes descendants; the 40 highest-weight stacks are retained. Open the interactive profiles to zoom and inspect full call paths."}),a(e,{src:"/examples/bibliography/figures/profile-allocations.png",alt:"Recorded Bibliography export flame graph weighted by sampled allocation bytes",caption:"A real capture at revision 575ec81, weighted by sampled allocation bytes. Width includes descendants; the 40 highest-weight stacks are retained. Open the interactive profiles to zoom and inspect full call paths."})])}const f=i(n,[["render",c]]);export{g as __pageData,f as default};
